    });
  });

  // FIVE: Accessibility (Right. Skip a bit.)
  describe('5. Accessibility', () => {
    it('shall have no violations', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });
  });

  // SIX: Edge Cases
  describe('6. Edge Cases - The Vorpal Scenarios', () => {
    it('shall show empty cart message when cart is empty', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout />);
      expect(screen.getByText(/your cart is empty/i)).toBeInTheDocument();
    });
